function lb_rows_bust(?string $file=null): void {if($file===null){unset($GLOBALS['lb_rows_cache'],$GLOBALS['lb_slots_cache']);return;}unset($GLOBALS['lb_rows_cache'][$file]);if($file===LB_RECORDS_FILE)unset($GLOBALS['lb_slots_cache']);}
function lb_rows(string $file): array {if(!isset($GLOBALS['lb_rows_cache'])||!is_array($GLOBALS['lb_rows_cache']))$GLOBALS['lb_rows_cache']=[];if(array_key_exists($file,$GLOBALS['lb_rows_cache']))return$GLOBALS['lb_rows_cache'][$file];if($file===LB_RECORDS_FILE&&cds_lb_read_effective()){try{return$GLOBALS['lb_rows_cache'][$file]=cds_lb_sql_all();}catch(Throwable$e){$GLOBALS['cds_force_json_lb_read']=true;error_log('[CDS lesson book SQL fallback] '.$e->getMessage());}}$v=load_json($file,[]);return$GLOBALS['lb_rows_cache'][$file]=is_array($v)?array_values(array_filter($v,'is_array')):[];}
function lb_write(string $file,array $rows): bool {
 $GLOBALS['lb_write_error']='';
 if($file!==LB_RECORDS_FILE){$ok=(bool)save_json($file,array_values($rows));if($ok)lb_rows_bust($file);return$ok;}
 $touched=[];$ok=cds_json_update($file,function($current)use($rows,&$touched){
  $map=[];foreach(array_values(array_filter(is_array($current)?$current:[],'is_array'))as$r){$id=(string)($r['slot_id']??'');if($id!=='')$map[$id]=$r;}
  foreach($rows as$r){if(!is_array($r))continue;$id=(string)($r['slot_id']??'');if($id==='')continue;$old=$map[$id]??null;$newTime=strtotime((string)($r['updated_at']??$r['created_at']??''))?:0;$oldTime=is_array($old)?(strtotime((string)($old['updated_at']??$old['created_at']??''))?:0):-1;if($old!==null&&$newTime>0&&$oldTime>0&&$newTime<$oldTime)continue;if($old!==$r)$touched[$id]=$r;$map[$id]=$r;}
  foreach($touched as$id=>$r){if(!cds_lb_claims_ppct((array)$r))continue;$target=cds_lb_enrich($r);$period=(int)$target['ppct_period'];$prior=$period<=1;foreach($map as$otherId=>$other){if($otherId===$id||!cds_lb_claims_ppct((array)$other))continue;$other=cds_lb_enrich($other);if($other['school_year_key']!==$target['school_year_key']||$other['class_key']!==$target['class_key']||$other['subject_key']!==$target['subject_key'])continue;$used=(int)($other['ppct_period']??0);if($used===$period){$GLOBALS['lb_write_error']='Tiết PPCT '.$period.' môn '.($target['subject']??'').' lớp '.($target['class']??'').' đã được một tiết khác ký trước.';return false;}if($used===$period-1)$prior=true;}if($period>1&&!$prior){$GLOBALS['lb_write_error']='Chưa thể ký tiết PPCT '.$period.': chưa có tiết '.($period-1).' đã ký cùng năm học, lớp và môn.';return false;}}
  return array_values($map);
 },[]);
 if(!$ok){if(($GLOBALS['lb_write_error']??'')==='')$GLOBALS['lb_write_error']='Không ghi được file sổ đầu bài. Vui lòng thử lại.';return false;}
 lb_rows_bust($file);
 foreach($touched as$r)if(!cds_lb_shadow_upsert($r)){$GLOBALS['cds_force_json_lb_read']=true;}
 return true;
}
function lb_class_student_names(string $class): array {
 $class=trim($class);if($class==='')return[];
 if(!isset($GLOBALS['lb_class_students'])||!is_array($GLOBALS['lb_class_students'])){
  $map=[];
  try{
   $rows=[];
   if(function_exists('csdl_students_all'))$rows=csdl_students_all();
   elseif(function_exists('csdl_get_students'))$rows=csdl_get_students();
   $classNames=[];if(function_exists('csdl_classes_all'))foreach(csdl_classes_all()as$c)$classNames[(string)($c['id']??'')]=trim((string)($c['name']??''));
   foreach((array)$rows as$stu){if(!is_array($stu))continue;if(array_key_exists('active',$stu)&&empty($stu['active']))continue;$name=trim((string)($stu['name']??$stu['ho_ten']??''));if($name==='')continue;$cls=trim((string)($stu['class_name']??$stu['class']??$stu['lop']??''));if($cls===''&&!empty($stu['class_id']))$cls=$classNames[(string)$stu['class_id']]??'';if($cls==='')continue;$nk=lb_norm($cls);if($nk==='')continue;$map[$nk][$name]=true;$map[lb_norm(preg_replace('/^lớp\s+/iu','',$cls))][$name]=true;}
   foreach($map as$k=>$names){$list=array_keys($names);usort($list,fn($a,$b)=>strnatcasecmp($a,$b));$map[$k]=$list;}
  }catch(Throwable $e){error_log('[CDS lb students] '.$e->getMessage());$map=[];}
  $GLOBALS['lb_class_students']=$map;
 }
 $key=lb_norm($class);$alt=lb_norm(preg_replace('/^lớp\s+/iu','',$class));
 return $GLOBALS['lb_class_students'][$key]??$GLOBALS['lb_class_students'][$alt]??[];
}
function lb_visible_class_students(array $rows): array {
 $out=[];foreach($rows as$r){$cls=trim((string)($r['class']??''));if($cls===''||isset($out[$cls]))continue;$out[$cls]=lb_class_student_names($cls);}return $out;
}
function lb_id(string $prefix='lb'): string { return $prefix.'_'.date('YmdHis').'_'.bin2hex(random_bytes(4)); }
function lb_user(): array { return (array)(cds_user()?:[]); }
function lb_is_admin(): bool { return (lb_user()['role']??'')==='admin'; }
function lb_is_management(): bool {$u=lb_user();return lb_is_admin()||($u['role']??'')==='bgh'||in_array('bgh',(array)($u['groups']??[]),true);}
function lb_is_leader(): bool { $u=lb_user(); return ($u['role']??'')==='totruong'||in_array('totruong',(array)($u['groups']??[]),true); }
function lb_teacher_name(): string { $u=lb_user(); return trim((string)($u['teacher_name']??$u['name']??$u['full_name']??'')); }
function lb_norm(string $v): string { return tkb_key($v); }
function lb_same(string $a,string $b): bool { return lb_norm($a)!==''&&lb_norm($a)===lb_norm($b); }
function lb_subject_key(string $subject):string{return cds_lb_subject_key($subject);}
function lb_same_subject(string $a,string $b):bool{return lb_subject_key($a)!==''&&lb_subject_key($a)===lb_subject_key($b);}
function lb_settings(): array {$s=array_replace_recursive(['grace_days'=>1,'lock_time'=>'23:59','auto_lock'=>false,'rating_points'=>['Tốt'=>10,'Khá'=>8,'Trung bình'=>6,'Yếu'=>4],'print'=>['paper'=>'a4_pair','scope'=>'class','session'=>'all','only_filled'=>false,'include_cover'=>true,'mirrored_margins'=>true,'leader_name'=>'','homeroom_name'=>'']],(array)load_json(LB_SETTINGS_FILE,[]));$s['auto_lock']=false;return$s;}
function lb_print_validation(array $rows): array {$v=['total'=>count($rows),'filled'=>0,'missing_content'=>0,'missing_signature'=>0,'pending'=>0];foreach($rows as$r){$filled=trim((string)($r['lesson_title']??''))!==''||trim((string)($r['teacher_comment']??''))!==''||(string)($r['status']??'pending')!=='pending';if(!$filled)continue;$v['filled']++;if(trim((string)($r['lesson_title']??''))==='')$v['missing_content']++;if(empty($r['signed_at']))$v['missing_signature']++;if((string)($r['status']??'pending')==='pending')$v['pending']++;}return$v;}
function lb_weeks(): array { return function_exists('cds_school_week_calendar')?cds_school_week_calendar():[]; }
function lb_week(string $key=''): ?array { $weeks=lb_weeks(); if($key!=='')foreach($weeks as $w)if((string)($w['key']??'')===$key)return$w; $today=date('Y-m-d'); foreach($weeks as $w)if($today>=($w['start']??'')&&$today<=($w['end']??''))return$w; if(!$weeks)return null;$last=end($weeks);return is_array($last)?$last:null; }
function lb_tkb_week(array $week): ?array { foreach(tkb_weeks() as $w){if(($w['start_date']??'')===($week['start']??''))return$w;if(lb_norm((string)($w['label']??''))===lb_norm((string)($week['label']??'')))return$w;} return null; }
function lb_grade(string $class): string { return preg_match('/\d+/', $class,$m)?$m[0]:''; }
