function lb_record_map(): array { $out=[]; foreach(lb_rows(LB_RECORDS_FILE) as $r)$out[(string)($r['slot_id']??'')]=$r; return$out; }
function lb_curriculum(): array { return lb_rows(LB_CURRICULUM_FILE); }
function lb_curriculum_permissions(): array { return lb_rows(LB_CURRICULUM_PERMISSIONS_FILE); }
function lb_curriculum_scopes(?string $teacher=null): array {$teacher=trim((string)($teacher??lb_teacher_name()));$all=$teacher===''&&lb_is_admin();$out=[];$seen=[];if($teacher===''&&!$all)return[];foreach(get_assignments()as$r){if(!is_array($r)||(!$all&&!lb_same($teacher,(string)($r['teacher']??''))))continue;$subject=trim((string)($r['subject']??''));$grade=lb_grade((string)($r['class']??$r['class_name']??''));$key=lb_norm($subject).'|'.$grade;if($subject!==''&&$grade!==''&&!isset($seen[$key])){$out[]=['subject'=>$subject,'grade'=>$grade];$seen[$key]=true;}}usort($out,fn($a,$b)=>[(int)$a['grade'],lb_norm($a['subject'])]<=>[(int)$b['grade'],lb_norm($b['subject'])]);return$out;}
function lb_curriculum_pccm_scope_rows(): array {$out=[];foreach(get_assignments()as$r){if(!is_array($r))continue;$teacher=trim((string)($r['teacher']??''));$subject=trim((string)($r['subject']??''));$grade=lb_grade((string)($r['class']??$r['class_name']??''));if($teacher===''||$subject===''||$grade==='')continue;$key=lb_norm($teacher).'|'.lb_norm($subject).'|'.$grade;$out[$key]=['teacher'=>$teacher,'subject'=>$subject,'grade'=>$grade];}$out=array_values($out);usort($out,fn($a,$b)=>strnatcasecmp($a['teacher'].'|'.$a['subject'].'|'.$a['grade'],$b['teacher'].'|'.$b['subject'].'|'.$b['grade']));return$out;}
function lb_can_manage_curriculum(string $subject='',string $grade=''): bool {if(lb_is_admin())return true;$grade=preg_replace('/\D+/','',$grade);foreach(lb_curriculum_scopes()as$scope)if(($subject===''||lb_subject_match($subject,$scope['subject']))&&($grade===''||$grade===(string)$scope['grade']))return true;return false;}
function lb_curriculum_visible_rows(): array {if(lb_is_admin())return lb_curriculum();return array_values(array_filter(lb_curriculum(),fn($r)=>lb_can_manage_curriculum((string)($r['subject']??''),(string)($r['grade']??''))));}
function lb_curriculum_scope_exists(string $subject,string $grade): bool {$grade=preg_replace('/\D+/','',$grade);foreach(lb_curriculum()as$r)if(lb_subject_match($subject,(string)($r['subject']??''))&&$grade===preg_replace('/\D+/','',(string)($r['grade']??'')))return true;return false;}
function lb_delete_curriculum_scope(string $subject,string $grade): array {if(!lb_is_admin())return['ok'=>false,'message'=>'Chỉ quản trị được xóa PPCT.'];$subject=trim($subject);$grade=preg_replace('/\D+/','',$grade);if($subject===''||$grade==='')return['ok'=>false,'message'=>'Chọn môn và khối cần xóa.'];$rows=lb_curriculum();$kept=[];$deleted=0;foreach($rows as$r){if(lb_subject_match($subject,(string)($r['subject']??''))&&$grade===preg_replace('/\D+/','',(string)($r['grade']??''))){$deleted++;continue;}$kept[]=$r;}if(!$deleted)return['ok'=>false,'message'=>'Không tìm thấy PPCT môn '.$subject.' khối '.$grade.'.'];if(!lb_write(LB_CURRICULUM_FILE,$kept))return['ok'=>false,'message'=>'Không xóa được PPCT.'];lb_audit('delete_curriculum_scope',['subject'=>$subject,'grade'=>$grade,'deleted'=>$deleted]);return['ok'=>true,'message'=>'Đã xóa '.$deleted.' dòng PPCT '.$subject.' khối '.$grade.'. Giáo viên có thể tải lại tệp mới.'];}
function lb_save_curriculum_permission(array $in): array {if(!lb_is_admin())return['ok'=>false,'message'=>'Chỉ quản trị được phân quyền cập nhật PPCT.'];$teacher=trim((string)($in['teacher']??''));$subject=trim((string)($in['subject']??''));$grade=preg_replace('/\D+/','',(string)($in['grade']??''));if($teacher===''||$subject===''||!in_array((int)$grade,[6,7,8,9,10,11,12],true))return['ok'=>false,'message'=>'Chọn đủ giáo viên, môn học và khối.'];$rows=lb_curriculum_permissions();foreach($rows as&$r)if(lb_same($teacher,(string)($r['teacher']??''))&&lb_subject_match($subject,(string)($r['subject']??''))&&$grade===preg_replace('/\D+/','',(string)($r['grade']??''))){$r['active']=true;$r['updated_at']=date('c');$r['updated_by']=lb_teacher_name();lb_write(LB_CURRICULUM_PERMISSIONS_FILE,$rows);return['ok'=>true,'message'=>'Đã khôi phục quyền PPCT cho giáo viên.'];}unset($r);$rows[]=['id'=>lb_id('ppctperm'),'teacher'=>$teacher,'subject'=>$subject,'grade'=>$grade,'active'=>true,'created_at'=>date('c'),'created_by'=>lb_teacher_name()];if(!lb_write(LB_CURRICULUM_PERMISSIONS_FILE,$rows))return['ok'=>false,'message'=>'Không lưu được phân quyền PPCT.'];lb_audit('grant_curriculum',['teacher'=>$teacher,'subject'=>$subject,'grade'=>$grade]);return['ok'=>true,'message'=>'Đã cấp quyền đưa PPCT lên cho '.$teacher.' · '.$subject.' · khối '.$grade.'.'];}
function lb_revoke_curriculum_permission(string $id): array {if(!lb_is_admin())return['ok'=>false,'message'=>'Chỉ quản trị được thu hồi quyền PPCT.'];$rows=lb_curriculum_permissions();$found=false;$detail=[];foreach($rows as&$r)if(($r['id']??'')===$id){$r['active']=false;$r['updated_at']=date('c');$r['updated_by']=lb_teacher_name();$detail=$r;$found=true;break;}unset($r);if(!$found)return['ok'=>false,'message'=>'Không tìm thấy quyền cần thu hồi.'];if(!lb_write(LB_CURRICULUM_PERMISSIONS_FILE,$rows))return['ok'=>false,'message'=>'Không lưu được thay đổi phân quyền.'];lb_audit('revoke_curriculum',$detail);return['ok'=>true,'message'=>'Đã thu hồi quyền cập nhật PPCT.'];}
function lb_subject_match(string $a,string $b):bool{$a=function_exists('tkb_subject_canonical')?tkb_subject_canonical($a):$a;$b=function_exists('tkb_subject_canonical')?tkb_subject_canonical($b):$b;/* PPCT must distinguish Nghệ thuật (Mỹ thuật) and Nghệ thuật (Âm nhạc); related-subject matching is only for teacher-fit logic. */return lb_same_subject($a,$b);}
function lb_curriculum_index():array{if(isset($GLOBALS['lb_curriculum_index'])&&is_array($GLOBALS['lb_curriculum_index']))return$GLOBALS['lb_curriculum_index'];$idx=['_all'=>[]];foreach(lb_curriculum()as$r){$subject=trim((string)($r['subject']??''));$grade=preg_replace('/\D+/','',(string)($r['grade']??''));$period=(int)($r['period']??0);if($subject===''||$grade===''||$period<1)continue;$keys=array_unique(array_filter([lb_subject_key($subject).'|'.$grade,lb_norm($subject).'|'.$grade,$subject.'|'.$grade]));foreach($keys as$k){$idx[$k][$period]=$r;$idx['_subj'][$k][]=$r;}$idx['_all'][$grade][]=$r;}return$GLOBALS['lb_curriculum_index']=$idx;}
function lb_curriculum_for(string $subject,string $grade,$ppct): ?array {
 $grade=preg_replace('/\D+/','',(string)$grade);$ppct=(int)$ppct;if($ppct<1)return null;
 $idx=lb_curriculum_index();
 foreach([lb_subject_key($subject).'|'.$grade,lb_norm($subject).'|'.$grade,$subject.'|'.$grade] as$k){if(!empty($idx[$k][$ppct]))return$idx[$k][$ppct];}
 foreach(($idx['_all'][$grade]??[]) as$r){if((int)($r['period']??0)!==$ppct)continue;$ps=(string)($r['subject']??'');if(lb_subject_match($subject,$ps)||lb_same_subject($subject,$ps))return$r;$a=lb_subject_key($subject);$b=lb_subject_key($ps);if($a!==''&&$b!==''&&(str_contains($a,$b)||str_contains($b,$a)))return$r;}
 return null;
}
function lb_curriculum_titles_for(string $subject,string $grade):array{$grade=preg_replace('/\D+/','',(string)$grade);$k=lb_subject_key($subject).'|'.$grade;$out=[];foreach((array)(lb_curriculum_index()[$k]??[])as$period=>$r){$title=trim((string)($r['title']??''));if((int)$period>0&&$title!=='')$out[(string)$period]=$title;}if($out){ksort($out,SORT_NUMERIC);return$out;}foreach(lb_curriculum()as$r)if(lb_subject_match((string)($r['subject']??''),$subject)&&preg_replace('/\D+/','',(string)($r['grade']??''))===$grade){$period=(int)($r['period']??0);$title=trim((string)($r['title']??''));if($period>0&&$title!=='')$out[(string)$period]=$title;}ksort($out,SORT_NUMERIC);return$out;}
function lb_ppct_used_periods(string $class,string $subject,string $excludeSlotId='',?array $rows=null,string $schoolYear=''):array{if($schoolYear===''){$year=cds_school_year_resolve();$schoolYear=(string)($year['id']??$year['label']??'');}$out=[];foreach($rows??lb_rows(LB_RECORDS_FILE)as$r){if($excludeSlotId!==''&&(string)($r['slot_id']??'')===$excludeSlotId)continue;$period=(int)($r['ppct_period']??0);if($schoolYear!==''&&cds_lb_school_year_key($r)!==$schoolYear)continue;if(!cds_lb_claims_ppct((array)$r)||!lb_same($class,(string)($r['class']??''))||!lb_same_subject($subject,(string)($r['subject']??'')))continue;$out[$period]=$r;}ksort($out,SORT_NUMERIC);return$out;}
function lb_ppct_next_period(array $used):int{$n=1;while(isset($used[$n])||isset($used[(string)$n]))$n++;return$n;}
function lb_saved_row_for_base(array $saved,array $allRecords,array $base,array &$matched=[]):array{
 $slotId=(string)($base['slot_id']??'');$direct=$slotId!==''&&!empty($saved[$slotId])&&is_array($saved[$slotId])&&empty($matched[$slotId])?$saved[$slotId]:[];
 $candidates=[];foreach($allRecords as$record){if(!is_array($record))continue;$recordId=(string)($record['slot_id']??'');if($recordId!==''&&!empty($matched[$recordId]))continue;if((string)($record['date']??'')!==(string)($base['date']??''))continue;$recWeek=trim((string)($record['week_key']??''));$baseWeek=trim((string)($base['week_key']??''));if($recWeek!==''&&$baseWeek!==''&&$recWeek!==$baseWeek)continue;if(!lb_same((string)($record['class']??''),(string)($base['class']??'')))continue;if(!lb_same_subject((string)($record['subject']??''),(string)($base['subject']??'')))continue;if((string)($record['book_type']??'main')!==(string)($base['book_type']??'main'))continue;$candidates[]=$record;}
 $signedLoose=[];foreach($allRecords as$record){if(!is_array($record)||empty($record['signed_at']))continue;if((string)($record['date']??'')!==(string)($base['date']??''))continue;if((string)($record['class']??'')!==(string)($base['class']??''))continue;if((string)($record['week_key']??'')!==''&&(string)($record['week_key']??'')!==$baseWeek)continue;if((string)($record['session']??'')===(string)($base['session']??'')&&(int)($record['period']??0)===(int)($base['period']??0))$signedLoose[]=$record;}$signed=array_values(array_filter($candidates,fn($record)=>!empty($record['signed_at'])));if($signed)$candidates=$signed;elseif($signedLoose)$candidates=$signedLoose;elseif($direct)$candidates=[$direct];
 if($candidates){usort($candidates,function($a,$b)use($base){$aSession=lb_norm((string)($a['session']??''))===lb_norm((string)($base['session']??''))?0:100;$bSession=lb_norm((string)($b['session']??''))===lb_norm((string)($base['session']??''))?0:100;$aDistance=$aSession+abs((int)($a['period']??0)-(int)($base['period']??0));$bDistance=$bSession+abs((int)($b['period']??0)-(int)($base['period']??0));return$aDistance<=>$bDistance?:strcmp((string)($b['updated_at']??$b['signed_at']??''),(string)($a['updated_at']??$a['signed_at']??''));});$record=$candidates[0];$recordId=(string)($record['slot_id']??'');if($recordId!=='')$matched[$recordId]=true;return$record;}
 return[];
}
function lb_record_before_week(array $record,array $week):bool{
 $start=trim((string)($week['start']??''));
 $date=trim((string)($record['date']??''));
 if($start!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))return $date<$start;
 $recordWeek=trim((string)($record['week_key']??''));$targetWeek=trim((string)($week['key']??''));
 if($recordWeek===''||$targetWeek===''||$recordWeek===$targetWeek)return false;
 $positions=[];foreach(lb_weeks()as$i=>$calendarWeek)$positions[(string)($calendarWeek['key']??'')]=$i;
