 $row['signed_at']=date('c');
 $row['signed_by']=lb_teacher_name();
 $row['updated_at']=date('c');
 $row['updated_by']=lb_teacher_name();
 if($sig){$row['signature_path']=$sig['path'];$row['signature_version']=$sig['version'];}
 else{unset($row['signature_path'],$row['signature_version']);}
 if(!lb_write(LB_RECORDS_FILE,[$row]))return['ok'=>false,'message'=>trim((string)($GLOBALS['lb_write_error']??''))?:'Đã lưu nội dung nhưng không ghi được trạng thái ký. Vui lòng thử lại.'];
