 return $sig
  ? ['ok'=>true,'message'=>'Đã lưu nội dung, gán chữ ký và họ tên giáo viên.']
  : ['ok'=>true,'type'=>'warning','message'=>'Đã lưu và ký bằng họ tên giáo viên. Tài khoản chưa có ảnh chữ ký; bạn có thể bổ sung ảnh chữ ký sau trong tab Chữ ký.'];
}
