function lb_sign(array $week,string $slotId): array {
 $slot=null;foreach(lb_slots($week)as$r)if(($r['slot_id']??'')===$slotId){$slot=$r;break;}
 if(!$slot)return['ok'=>false,'message'=>'Không tìm thấy tiết học.'];
 if(!lb_can_edit($slot))return['ok'=>false,'message'=>'Bạn không được ký tiết này.'];
 if(lb_locked($week,$slot))return['ok'=>false,'message'=>'Sổ đã khóa.'];
 $row=[];foreach(lb_rows(LB_RECORDS_FILE)as$r)if(($r['slot_id']??'')===$slotId){$row=$r;break;}
 if(!$row)return['ok'=>false,'message'=>'Hãy lưu nội dung tiết trước khi ký.'];
 $sig=lb_signature_meta();
 $row['signed_at']=date('c');$row['signed_by']=lb_teacher_name();$row['updated_at']=date('c');$row['updated_by']=lb_teacher_name();
 if($sig){$row['signature_path']=$sig['path'];$row['signature_version']=$sig['version'];}else unset($row['signature_path'],$row['signature_version']);
 unset($row['suggested_ppct_period'],$row['used_ppct_periods']);
 if(!lb_write(LB_RECORDS_FILE,[$row]))return['ok'=>false,'message'=>trim((string)($GLOBALS['lb_write_error']??''))?:'Không ghi được trạng thái ký.'];
 lb_audit('sign_record',['slot_id'=>$slotId,'signature_version'=>$sig['version']??'','signed_by'=>lb_teacher_name(),'signature_missing'=>!$sig]);
 return$sig?['ok'=>true,'message'=>'Đã gán chữ ký và họ tên giáo viên.']:['ok'=>true,'type'=>'warning','message'=>'Đã ký bằng họ tên giáo viên. Tài khoản chưa có ảnh chữ ký.'];
}
function lb_save_curriculum(array $in): array {if(!lb_is_admin())return['ok'=>false,'message'=>'Chỉ quản trị được sửa PPCT.'];$subject=trim((string)($in['subject']??''));$grade=preg_replace('/\D+/','',trim((string)($in['grade']??'')));$period=(int)($in['period']??0);$title=trim((string)($in['title']??''));if($subject===''||$grade===''||$period<1||$title==='')return['ok'=>false,'message'=>'Nhập đủ môn, khối, tiết PPCT và tên bài.'];$rows=lb_curriculum();$found=false;foreach($rows as&$r)if(lb_same((string)($r['subject']??''),$subject)&&(string)$r['grade']===$grade&&(int)$r['period']===$period){$r=array_merge($r,['subject'=>$subject,'grade'=>$grade,'period'=>$period,'title'=>$title]);$found=true;break;}unset($r);if(!$found)$rows[]=['id'=>lb_id('ppct'),'subject'=>$subject,'grade'=>$grade,'period'=>$period,'title'=>$title];lb_write(LB_CURRICULUM_FILE,$rows);return['ok'=>true,'message'=>'Đã lưu PPCT.'];}
