 if(!$isAdmin){
  $outside=[];foreach($incoming as$item)if(!lb_same($targetSubject,(string)$item['subject'])||$targetGrade!==(string)$item['grade'])$outside[]=(string)$item['subject'].' – Khối '.(string)$item['grade'];
  if($outside)return['ok'=>false,'message'=>'KHÔNG NHẬP DỮ LIỆU: tệp có Môn–Khối ngoài lựa chọn '.$targetSubject.' – Khối '.$targetGrade.' ('.implode(', ',array_slice(array_values(array_unique($outside)),0,5)).'). Mỗi tệp chỉ được chứa một Môn–Khối.'];
  if(lb_curriculum_scope_exists($targetSubject,$targetGrade))return['ok'=>false,'message'=>'PPCT '.$targetSubject.' – Khối '.$targetGrade.' đã tồn tại. Giáo viên không được ghi đè; hãy liên hệ quản trị để kiểm tra hoặc xóa bản cũ trước khi tải lại.'];
 }
 $rows=lb_curriculum();$index=[];foreach($rows as$i=>$r)$index[lb_norm((string)($r['subject']??'')).'|'.preg_replace('/\D+/','',(string)($r['grade']??'')).'|'.(int)($r['period']??0)]=$i;$added=0;$updated=0;
 foreach($incoming as$key=>$item){if(isset($index[$key])){$rows[$index[$key]]=array_merge($rows[$index[$key]],$item,['updated_at'=>date('c'),'updated_by'=>lb_teacher_name()]);$updated++;}else{$rows[]=array_merge(['id'=>lb_id('ppct')],$item,['created_at'=>date('c'),'created_by'=>lb_teacher_name()]);$added++;}}
 usort($rows,function($a,$b){$ga=(int)preg_replace('/\D+/','',(string)($a['grade']??0));$gb=(int)preg_replace('/\D+/','',(string)($b['grade']??0));return$ga<=>$gb?:strnatcasecmp((string)($a['subject']??''),(string)($b['subject']??''))?:(int)($a['period']??0)<=>(int)($b['period']??0);});
 if(!lb_write(LB_CURRICULUM_FILE,$rows))return['ok'=>false,'message'=>'Không ghi được dữ liệu PPCT.'];lb_audit('import_curriculum',['added'=>$added,'updated'=>$updated,'total'=>count($incoming),'warnings'=>count($warnings)]);$scopeLabel=['year'=>'cả năm học','1'=>'học kỳ 1','2'=>'học kỳ 2'][$ppctScope]??'cả năm học';$msg='Đã kiểm tra và nhập '.count($incoming).' dòng PPCT ('.$scopeLabel.'): thêm '.$added.', cập nhật '.$updated.'.';if($warnings)$msg.=' Cảnh báo: '.implode(' ',array_slice($warnings,0,5)).(count($warnings)>5?' …':'');return['ok'=>true,'message'=>$msg];
}
function lb_stat_rows(string $from,string $to,string $teacher='',string $subject='',string $class='',string $completion='all'): array {$out=[];$savedMap=lb_record_map();foreach(lb_weeks()as$statWeek){$start=(string)($statWeek['start']??'');$end=(string)($statWeek['end']??'');if(($to!==''&&$start>$to)||($from!==''&&$end<$from))continue;foreach(lb_slots($statWeek,$savedMap)as$r){$date=(string)($r['date']??'');if($date===''||($from!==''&&$date<$from)||($to!==''&&$date>$to)||!lb_can_view($r))continue;$rowTeacher=(string)($r['actual_teacher']??$r['scheduled_teacher']??'');if($teacher!==''&&!lb_same($teacher,$rowTeacher))continue;if($subject!==''&&!lb_subject_match($subject,(string)($r['subject']??'')))continue;if($class!==''&&!lb_same($class,(string)($r['class']??'')))continue;$saved=!empty($r['created_at'])||!empty($r['updated_at']);$signed=!empty($r['signed_at']);if($completion==='completed'&&!$signed)continue;if($completion==='incomplete'&&$signed)continue;if($completion==='saved_unsigned'&&(!$saved||$signed))continue;if($completion==='not_saved'&&$saved)continue;$r['_saved']=$saved;$r['_completed']=$signed;$out[]=$r;}}usort($out,fn($a,$b)=>strcmp((string)($a['date']??''),(string)($b['date']??''))?:strnatcasecmp((string)($a['class']??''),(string)($b['class']??''))?:(int)($a['period']??0)<=>(int)($b['period']??0));return$out;}
function lb_stat_status(array $r): string {$st=trim((string)($r['status']??''));return $st!==''?$st:((!empty($r['signed_at'])||!empty($r['_completed']))?'taught':'pending');}
function lb_stat_group(array $rows,string $field): array {
 $keys=['taught','substitute','makeup','online','holiday','teacher_absent','class_absent','postponed','cancelled','pending'];
 $groups=[];
 foreach($rows as$r){
  $name=trim((string)($r[$field]??''));
  if($field==='actual_teacher'&&$name==='')$name=trim((string)($r['scheduled_teacher']??''));
  if($field==='week_label'&&$name==='')$name=trim((string)($r['week_key']??'Tuần'));
  if($name==='')$name='Chưa xác định';
  if(!isset($groups[$name])){$groups[$name]=['name'=>$name,'scheduled'=>0,'saved'=>0,'completed'=>0,'incomplete'=>0,'actual'=>0.0,'off'=>0];foreach($keys as$k)$groups[$name][$k]=0;}
  $groups[$name]['scheduled']++;
  $saved=!empty($r['_saved'])||!empty($r['created_at'])||!empty($r['updated_at']);
  $signed=!empty($r['signed_at'])||!empty($r['_completed']);
  if($saved)$groups[$name]['saved']++;
  if($signed)$groups[$name]['completed']++;else$groups[$name]['incomplete']++;
  $status=lb_stat_status($r);
  if(isset($groups[$name][$status]))$groups[$name][$status]++;
  if(in_array($status,['taught','substitute','makeup','online'],true))$groups[$name]['actual']+=(float)($r['actual_periods']??1);
  if(in_array($status,['holiday','teacher_absent','class_absent','postponed','cancelled'],true))$groups[$name]['off']++;
 }
 uasort($groups,fn($a,$b)=>$b['scheduled']<=>$a['scheduled']?:strnatcasecmp($a['name'],$b['name']));
 return array_values($groups);
}
function lb_stat_totals(array $rows): array {
 $g=lb_stat_group($rows,'__all');
 if(!$g)return ['name'=>'Tổng','scheduled'=>0,'saved'=>0,'completed'=>0,'incomplete'=>0,'actual'=>0.0,'off'=>0,'taught'=>0,'substitute'=>0,'makeup'=>0,'online'=>0,'holiday'=>0,'teacher_absent'=>0,'class_absent'=>0,'postponed'=>0,'cancelled'=>0,'pending'=>0];
 $t=$g[0];$t['name']='Tổng';return $t;
}
function lb_set_lock(array $week,array $classes,bool $locked,string $reason=''): array {if(!lb_is_admin())return['ok'=>false,'message'=>'Chỉ quản trị được khóa/mở sổ.'];$rows=lb_rows(LB_LOCKS_FILE);foreach($classes as$class){$key=lb_lock_key((string)$week['key'],(string)$class,'main');$found=false;foreach($rows as&$r)if(($r['key']??'')===$key){$r=array_merge($r,['locked'=>$locked,'reason'=>$reason,'at'=>date('c'),'by'=>lb_teacher_name(),'automatic'=>false]);$found=true;break;}unset($r);if(!$found)$rows[]=['key'=>$key,'week_key'=>$week['key'],'class'=>$class,'type'=>'main','locked'=>$locked,'reason'=>$reason,'at'=>date('c'),'by'=>lb_teacher_name(),'automatic'=>false];}lb_write(LB_LOCKS_FILE,$rows);lb_audit($locked?'lock':'unlock',['classes'=>$classes,'reason'=>$reason]);return['ok'=>true,'message'=>$locked?'Đã khóa sổ.':'Đã mở khóa sổ.'];}
function lb_set_lock_bulk(array $weekKeys,string $scope,string $target,bool $locked,string $reason=''):array{if(!lb_is_admin())return['ok'=>false,'message'=>'Chỉ quản trị được khóa/mở sổ.'];$weekKeys=array_values(array_unique(array_filter(array_map('strval',$weekKeys))));if(!$weekKeys)return['ok'=>false,'message'=>'Hãy chọn ít nhất một tuần.'];if(!in_array($scope,['school','grade','class'],true))return['ok'=>false,'message'=>'Phạm vi khóa không hợp lệ.'];if($scope!=='school'&&trim($target)==='')return['ok'=>false,'message'=>'Hãy chọn khối hoặc lớp.'];$weeks=[];foreach(lb_weeks()as$week)if(in_array((string)($week['key']??''),$weekKeys,true))$weeks[]=$week;if(!$weeks)return['ok'=>false,'message'=>'Không tìm thấy tuần đã chọn.'];$rows=lb_rows(LB_LOCKS_FILE);$changed=0;$affected=[];foreach($weeks as$week){$classes=[];foreach(lb_slots($week)as$slot){$class=trim((string)($slot['class']??''));if($class==='')continue;if($scope==='grade'&&lb_grade($class)!==preg_replace('/\D+/','',$target))continue;if($scope==='class'&&!lb_same($class,$target))continue;$classes[$class]=true;}foreach(array_keys($classes)as$class){$key=lb_lock_key((string)$week['key'],$class,'main');$found=false;foreach($rows as&$row)if(($row['key']??'')===$key){$row=array_merge($row,['locked'=>$locked,'reason'=>$reason,'at'=>date('c'),'by'=>lb_teacher_name(),'automatic'=>false]);$found=true;break;}unset($row);if(!$found)$rows[]=['key'=>$key,'week_key'=>$week['key'],'class'=>$class,'type'=>'main','locked'=>$locked,'reason'=>$reason,'at'=>date('c'),'by'=>lb_teacher_name(),'automatic'=>false];$changed++;$affected[]=(string)$week['key'].'|'.$class;}}if(!$changed)return['ok'=>false,'message'=>'Phạm vi đã chọn không có lớp nào trong các tuần này.'];if(!lb_write(LB_LOCKS_FILE,$rows))return['ok'=>false,'message'=>'Không lưu được trạng thái khóa sổ.'];lb_audit($locked?'bulk_lock':'bulk_unlock',['weeks'=>$weekKeys,'scope'=>$scope,'target'=>$target,'affected'=>$changed,'reason'=>$reason]);return['ok'=>true,'message'=>($locked?'Đã khóa ':'Đã mở khóa ').$changed.' sổ lớp trong '.count($weeks).' tuần.'];}
